(()=>{'use strict';const $=x=>document.getElementById('M31-'+x),zh=document.documentElement.lang.startsWith('zh'),Y=[-1,-1,1,-1,1,1,-1,1];let s;const text=(x,y,v,c='#253746',size=17)=>`<text x="${x}" y="${y}" fill="${c}" font-size="${size}" font-family="sans-serif">${v}</text>`;
function draw(){const cut=+$('cut').value,polarity=+$('direction').value,eta=+$('rate').value,H=Y.map((_,i)=>polarity*(i+1<=cut?-1:1)),wrong=Y.map((y,i)=>y!==H[i]),error=wrong.filter(Boolean).length/8,alpha=eta*.5*Math.log((1-error)/error),raw=Y.map((y,i)=>Math.exp(-alpha*y*H[i])/8),den=raw.reduce((a,b)=>a+b,0),weights=raw.map(x=>x/den);s={cut,polarity,eta,error,alpha,weights,weight_sum:weights.reduce((a,b)=>a+b,0)};$('cut-value').textContent=cut;$('rate-value').textContent=eta.toFixed(1);let svg=text(24,35,zh?'真实标签 / 树桩预测':'True labels / stump predictions')+text(24,190,zh?'归一化权重：灰色为更新前，彩色为更新后':'Normalized weights: gray before, color after');const base=435,scale=430;[0,.125,.25,.5].forEach(v=>{const y=base-v*scale;svg+=`<line x1="85" y1="${y}" x2="855" y2="${y}" stroke="#d6dde2"/>`+text(24,y+5,v.toFixed(3),'#647585',14)});Y.forEach((y,i)=>{const x=125+94*i,c=wrong[i]?'#d87430':'#237b94';svg+=`<circle cx="${x}" cy="75" r="20" fill="#f1f5f6" stroke="${c}" stroke-width="${wrong[i]?3:1}"/>`+text(x-9,81,y>0?'+':'−',c,24)+text(x-9,126,H[i]>0?'+':'−',c,24)+`<rect x="${x-24}" y="${base-.125*scale}" width="20" height="${.125*scale}" fill="#bbc6cc"/><rect x="${x+3}" y="${base-weights[i]*scale}" width="20" height="${weights[i]*scale}" fill="${c}"/>`+text(x-16,base-weights[i]*scale-9,weights[i].toFixed(3),c,14)+text(x-5,463,i+1,'#253746',16)});const splitX=125+94*(cut-.5);svg+=`<line x1="${splitX}" y1="48" x2="${splitX}" y2="140" stroke="#253746" stroke-dasharray="5 4"/>`+text(355,491,zh?'记录编号（固定顺序）':'Record index (fixed order)');$('plot').innerHTML=svg;$('result').textContent=(zh?'加权错误率 ':'Weighted error ')+error.toFixed(3)+(zh?'；投票系数 ':'; voting coefficient ')+alpha.toFixed(6)+(zh?'；权重总和 ':'; weight sum ')+s.weight_sum.toFixed(6);}
function set(p={}){if(p.cut!==undefined)$('cut').value=Math.max(1,Math.min(7,Math.round(p.cut)));if(p.polarity!==undefined)$('direction').value=p.polarity<0?'-1':'1';if(p.eta!==undefined)$('rate').value=Math.max(.1,Math.min(1.5,+p.eta));draw();return s}function reset(){return set({cut:2,polarity:1,eta:1})}['cut','direction','rate'].forEach(id=>$(id).addEventListener('input',draw));$('reset').addEventListener('click',reset);window.CourseLab={set,state:()=>structuredClone(s),reset};reset()})();
